import json, sys
data = json.load(sys.stdin)
inner = json.loads(data['result']) if isinstance(data['result'], str) else data['result']
exps = inner['data']['experiments']

# Check for seed diversity - how many unique seeds are used?
seeds = set()
for eid, exp in exps.items():
    spec = exp.get('spec', {})
    if isinstance(spec, dict):
        seed = spec.get('seed')
        if seed is not None:
            seeds.add(str(seed))
print(f'Unique seeds found: {seeds}')

# Check min_phase_length values
mpl_values = set()
for eid, exp in exps.items():
    spec = exp.get('spec', {})
    if isinstance(spec, dict):
        cmd = spec.get('command', '')
        if 'min_phase_length' in cmd:
            import re
            m = re.search(r'min_phase_length\s+(\d+)', cmd)
            if m:
                mpl_values.add(m.group(1))
print(f'min_phase_length values: {mpl_values}')

# Count experiments by model
model_counts = {}
for eid, exp in exps.items():
    spec = exp.get('spec', {})
    if isinstance(spec, dict):
        model = spec.get('model_name', 'unknown')
        cmd = spec.get('command', '')
        if 'Qwen2.5' in cmd or 'qw' in eid.lower() or model == 'Qwen':
            model_counts['Qwen'] = model_counts.get('Qwen', 0) + 1
        elif 'Llama' in cmd or 'llama' in eid.lower():
            model_counts['LLaMA'] = model_counts.get('LLaMA', 0) + 1
        elif 'DeepSeek' in cmd or 'ds' in eid.lower() or model.startswith('DeepSeek'):
            model_counts['DeepSeek'] = model_counts.get('DeepSeek', 0) + 1
        else:
            model_counts['other/unclear'] = model_counts.get('other/unclear', 0) + 1
print(f'Experiments by model: {model_counts}')
